class Group:
    def __init__(self, members: list[str]) -> None:
        # Preserve order of members while eliminating duplicates or validating
        self._members = list(dict.fromkeys(members))
        self._member_set = set(self._members)
        self._balances = {m: 0.0 for m in self._members}

    def add_expense(
        self,
        payer: str,
        amount: float,
        participants: list[str] | None = None,
    ) -> None:
        """Record that `payer` paid `amount` on behalf of `participants`."""
        if amount <= 0:
            raise ValueError(f"Expense amount must be positive, got {amount}.")
        if payer not in self._member_set:
            raise ValueError(f"Payer '{payer}' is not a group member.")

        if participants is None:
            actual_participants = list(self._members)
        else:
            if not participants:
                raise ValueError("Participants list cannot be empty.")
            for p in participants:
                if p not in self._member_set:
                    raise ValueError(f"Participant '{p}' is not a group member.")
            actual_participants = list(participants)

        self._balances[payer] += amount
        split_share = amount / len(actual_participants)
        for p in actual_participants:
            self._balances[p] -= split_share

    def balances(self) -> dict[str, float]:
        """Net balance per member. Positive = the member is owed money,
        negative = the member owes money."""
        return {m: round(self._balances[m], 2) for m in self._members}

    def settle_up(self) -> list[tuple[str, str, float]]:
        """Payments that settle the group, as (debtor, creditor, amount)."""
        # Separate debtors and creditors, ignoring amounts strictly less than 1.00
        debtors: list[list[str | float]] = []
        creditors: list[list[str | float]] = []

        for m in self._members:
            bal = self._balances[m]
            if bal <= -1.00:
                debtors.append([m, -bal])
            elif bal >= 1.00:
                creditors.append([m, bal])

        payments: list[tuple[str, str, float]] = []

        d_idx = 0
        c_idx = 0

        while d_idx < len(debtors) and c_idx < len(creditors):
            debtor_name = str(debtors[d_idx][0])
            debt_amount = float(debtors[d_idx][1])

            creditor_name = str(creditors[c_idx][0])
            credit_amount = float(creditors[c_idx][1])

            transfer = min(debt_amount, credit_amount)

            if transfer >= 1.00:
                payments.append((debtor_name, creditor_name, round(transfer, 2)))

            remaining_debt = debt_amount - transfer
            remaining_credit = credit_amount - transfer

            debtors[d_idx][1] = remaining_debt
            creditors[c_idx][1] = remaining_credit

            if remaining_debt < 1.00:
                d_idx += 1
            if remaining_credit < 1.00:
                c_idx += 1

        return payments
